  _rh+=`<div class="note-body">Paid Cap: <strong>${pct(_m.cap)}</strong><br>GG% of Potential: <strong>${pct(_m.gg)}</strong><br>Avg Admission: <strong>${_m.adm!=null?'$'+fmtN(_m.adm,0):'—'}</strong><br><em>${_yieldGap!=null&&_yieldGap>15?'Strong attendance, weaker yield. Review pricing model.':_yieldGap!=null&&_yieldGap<=5&&_m.gg>=75?'Demand and revenue well-aligned.':'Review individual metrics in context.'}</em></div></div>`;
  // Q2: Revenue in comparable rooms
