function renderHistory(){const q=norm($('showSearch')?.value||'');const pastSeasons=SEASONS.filter(s=>seasonMode(s.id)==='past').sort((a,b)=>String(b.id).localeCompare(String(a.id)));const selected=SEASONS.find(s=>s.id===ACTIVE_SEASON&&seasonMode(s.id)==='past')||pastSeasons[0];const seasonRows=selected?selected.shows.map(profile).filter(p=>!q||norm(p.show.title).includes(q)||norm(p.show.match).includes(q)).sort(bySeasonDate):[];const names=[...new Set(ALL.map(d=>d.show).filter(Boolean))].filter(s=>!q||norm(s).includes(q)).slice(0,80);const library=names.map(s=>profile({title:s,match:s,sub:false})).filter(p=>p.metrics.count>0).sort((a,b)=>b.metrics.weeks-a.metrics.weeks).slice(0,30);const seasonAvgCap=avg(seasonRows.map(p=>p.metrics.cap));const seasonAvgGross=avg(seasonRows.map(p=>p.metrics.gross));const strong=seasonRows.filter(p=>p.score>=SCORE_MED).length;const watch=seasonRows.filter(p=>p.score<SCORE_MED&&p.metrics.count>0).length;$('tab-history').innerHTML=`<div class="section-divider"><h2>Show History</h2><div class="section-divider-line"></div><div class="section-divider-meta">Retrospective read: how did we do?</div></div><div class="explainer"><p><strong>Purpose:</strong> previous seasons are shown as completed performance reviews, not forecasts. The result index uses the same demand, revenue, peer, and sample-depth signals, but the interpretation is retrospective: what worked, what lagged, and what should inform future booking and marketing decisions.</p></div><div class="grid grid-4"><div class="kpi-card"><div class="kpi-label">Reviewed Season</div><div class="kpi-value">${selected?selected.id.slice(2,4)+'-'+selected.id.slice(7,9):'—'}</div><div class="kpi-note">selected season lens</div></div><div class="kpi-card"><div class="kpi-label">Avg Capacity</div><div class="kpi-value">${pct(seasonAvgCap,0)}</div><div class="kpi-note">season slate actuals</div></div><div class="kpi-card"><div class="kpi-label">Avg Gross</div><div class="kpi-value">${fmt$(seasonAvgGross)}</div><div class="kpi-note">matched touring records</div></div><div class="kpi-card"><div class="kpi-label">Strong / Watch</div><div class="kpi-value">${strong} / ${watch}</div><div class="kpi-note">performance result bands</div></div></div><div class="grid grid-2" style="margin-top:18px"><div class="card full"><div class="card-hd">${selected?selected.name:'Previous Season'} Performance Review</div><table class="mini-table"><thead><tr><th>Show</th><th>Pkg</th><th class="num">Result</th><th class="num">GG%</th><th>Revenue</th><th class="num">Cap</th><th>Demand</th><th class="num">Peer Cap</th><th class="num">Avg Gross</th><th>Confidence</th><th>Historical Read</th></tr></thead><tbody>${seasonRows.map(p=>rowHtml(p,'past')).join('')||'<tr><td colspan="8" class="empty">No programmed show records matched this season.</td></tr>'}</tbody></table></div>${bushnellVsMarketTable(seasonRows,selected?selected.id:'')}<div class="card"><div class="card-hd">Selected History</div><div id="historyDetail">${seasonRows[0]?detailHtml(seasonRows[0],'past'):(library[0]?detailHtml(library[0],'past'):'<div class="empty">Search for a show.</div>')}</div></div><div class="card"><div class="card-hd">Broader Historical Show Library</div><div class="card-sub">All matched touring titles, sorted by weeks reported.</div><table class="mini-table"><thead><tr><th>Show</th><th class="num">Weeks</th><th class="num">Cap</th><th class="num">Gross</th></tr></thead><tbody>${library.map(p=>`<tr onclick="historyDetail('${esc(p.show.title)}')" style="cursor:pointer"><td>${p.show.title}</td><td class="num">${p.metrics.weeks}</td><td class="num">${pct(p.metrics.cap)}</td><td class="num">${fmt$(p.metrics.gross)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function historyDetail(title){const p=profile({title,match:title,sub:false});$('historyDetail').innerHTML=detailHtml(p,'past')}
function renderFuture(){const future=seasonProfiles('2026-2027');const profiles=future.profiles.sort(bySeasonDate);$('tab-future').innerHTML=`<div class="section-divider"><h2>Future Planning</h2><div class="section-divider-line"></div><div class="section-divider-meta">${future.season.name} candidate read</div></div><div class="explainer"><p><strong>Purpose:</strong> this view is for season planning conversations. It compares next-season titles against existing tour evidence where available. New-tour titles are marked <strong>NEW</strong> when the static touring feed has no comparable historical records yet; leadership should treat those as open strategic bets, not failed scores.</p></div><div class="grid grid-3"><div class="card full"><div class="card-hd">Candidate Fit Scores</div><table class="mini-table"><thead><tr><th>Candidate</th><th>Pkg</th><th class="num">Fit</th><th class="num">Tour Cap</th><th>Demand</th><th class="num">GG%</th><th>Revenue</th><th class="num">Peer Cap</th><th class="num">Records</th><th>Confidence</th><th>Planning Read</th></tr></thead><tbody>${profiles.map(p=>{const cls=p.isFutureNewTour?'neutral':p.score>=SCORE_MED?'good':'warn';const scoreLabel=p.isFutureNewTour?'NEW':p.score;((_fs=planningSignals(p))=>`<tr><td>${p.show.title}<br><span style="color:var(--ink3);font-size:.58rem">${dateLine(p.show)}</span></td><td>${p.show.sub?'Sub':'Add-on'}</td><td class="num"><span class="status ${cls}">${scoreLabel}</span></td><td class="num">${pct(p.metrics.cap)}</td><td>${signalBadge(_fs.demand)}</td><td class="num">${pct(p.metrics.gg)}</td><td>${signalBadge(_fs.revenue)}</td><td class="num">${pct(p.metrics.peerCap)}</td><td class="num">${p.metrics.count}</td><td>${signalBadge(_fs.confidence)}</td><td>${_fs.planningRead}</td></tr>`)()}).join('')}</tbody></table></div><div class="card"><div class="card-hd">High Confidence</div><div class="card-sub">Titles with enough feed history to support a stronger planning read.</div><div class="rank-list">${rankItems(profiles.filter(p=>p.metrics.count>=5).slice(0,5),p=>p.show.title,p=>`${p.metrics.count} records · ${pct(p.metrics.cap,0)} cap`,p=>p.score)}</div></div><div class="card"><div class="card-hd">New / Needs Comparable Validation</div><div class="card-sub">Use outside context, artistic priorities, pre-sale signal, and comparable prior Bushnell titles.</div><div class="rank-list">${profiles.filter(p=>p.metrics.count<3).map((p,i)=>`<div class="rank-item"><div class="rank-n">${i+1}</div><div class="rank-body"><div class="rank-name">${p.show.title}</div><div class="rank-detail">${p.isFutureNewTour?'New-tour upside · no historical feed records':p.metrics.count+' matching records'} · ${confidenceLabel(p)}</div></div></div>`).join('')||'<div class="empty">All candidates have at least 3 matching records.</div>'}</div></div><div class="card"><div class="card-hd">Fit Distribution</div><canvas id="cFuture" class="small-canvas"></canvas></div></div>`;chartFit(profiles,'cFuture');}
function renderPeers(){const peer=ALL.filter(d=>isPeerType(d, ACTIVE_PEER||'size')&&d.gross_gross!=null);const by={};peer.forEach(d=>{const k=d.theatre+'|'+d.city;if(!by[k])by[k]={theatre:d.theatre,city:d.city,gross:0,caps:[],weeks:new Set(),count:0};by[k].gross+=d.gross_gross;by[k].caps.push(d.cap_paid);by[k].weeks.add(d.week_of);by[k].count++});const arr=Object.values(by).map(v=>({...v,cap:avg(v.caps),avgGross:v.gross/v.count,wks:v.weeks.size,meta:PEER_META[v.theatre+'|'+v.city]})).sort((a,b)=>b.wks-a.wks).slice(0,30);$('tab-peers').innerHTML=`<div class="section-divider"><h2>Peer Intelligence</h2><div class="section-divider-line"></div><div class="section-divider-meta">Bushnell-size venue benchmark from peers.json</div></div><div class="explainer"><p><strong>What are peers?</strong> Peers are venues flagged in the feed as similar to the Bushnell in per-show sellable capacity. This is more useful than raw venue size because Broadway tours report weekly capacity across the number of performances. Peer results help leadership ask: "How does this title behave in rooms like ours?"</p></div><div class="grid grid-2"><div class="card"><div class="card-hd">Top Peer Venues by Reporting Weeks</div><table class="mini-table"><thead><tr><th>Venue</th><th class="num">Weeks</th><th class="num">Cap</th><th class="num">Avg Gross</th></tr></thead><tbody>${arr.map(v=>{const types=(v.meta&&v.meta.peer_types)||[];const badges=types.map(t=>`<span class="peer-badge peer-badge-${t}">${t==='size_extended'?'Extended':t.charAt(0).toUpperCase()+t.slice(1)}</span>`).join(' ');return `<tr><td>${v.theatre}${badges}<br><span style="color:var(--ink3);font-size:.58rem">${v.city}${v.meta&&v.meta.state?', '+v.meta.state:''}</span></td><td class="num">${v.wks}</td><td class="num">${pct(v.cap)}</td><td class="num">${fmt$(v.avgGross)}</td></tr>`}).join('')}</tbody></table></div><div class="card"><div class="card-hd">Peer Capacity Distribution</div><canvas id="cPeers"></canvas></div><div class="card full"><div class="card-hd">Why This Matters</div><div class="grid grid-3"><div class="note"><div class="note-hd">Market Fit</div><div class="note-body">Peer venues reduce noise from very large or very small markets.</div></div><div class="note"><div class="note-hd">Programming</div><div class="note-body">A show that is average nationally but strong among peers may be a good Bushnell candidate.</div></div><div class="note"><div class="note-hd">Caution</div><div class="note-body">Peer performance is directional. It should be read with pricing, subscription, timing, and local audience knowledge.</div></div></div></div><div class="card full"><div class="card-hd">Peer Notes</div><div class="grid grid-3">${arr.slice(0,6).map(v=>`<div><div class="card-title" style="font-size:.82rem">${v.theatre}</div><div class="card-sub">${v.meta&&v.meta.synopsis?v.meta.synopsis:'Peer venue metadata available; synopsis not populated.'}</div></div>`).join('')}</div></div></div>`;chartPeers(arr)}
function renderOpportunity(){const all=[...new Set(ALL.map(d=>d.show).filter(Boolean))].map(s=>profile({title:s,match:s,sub:false})).filter(p=>p.metrics.count>=5);const hidden=all.filter(p=>p.metrics.peerCap!=null&&p.metrics.cap!=null&&p.metrics.peerCap>p.metrics.cap+8).sort((a,b)=>(b.metrics.peerCap-b.metrics.cap)-(a.metrics.peerCap-a.metrics.cap)).slice(0,10);const caution=all.filter(p=>p.metrics.peerCap!=null&&p.metrics.cap!=null&&p.metrics.peerCap<p.metrics.cap-8).sort((a,b)=>(a.metrics.peerCap-a.metrics.cap)-(b.metrics.peerCap-b.metrics.cap)).slice(0,10);const subLift=all.filter(p=>p.metrics.subCap!=null&&p.metrics.nonSubCap!=null).sort((a,b)=>(b.metrics.subCap-b.metrics.nonSubCap)-(a.metrics.subCap-a.metrics.nonSubCap)).slice(0,10);$('tab-opportunity').innerHTML=`<div class="section-divider"><h2>Opportunity Engine</h2><div class="section-divider-line"></div><div class="section-divider-meta">Signals for booking and marketing conversations</div></div><div class="explainer"><p><strong>Purpose:</strong> this page surfaces exceptions worth discussing. "Hidden gems" are not automatic bookings, and "cautions" are not rejections. They are prompts for leadership to ask why a title over- or under-performs in Bushnell-like rooms.</p></div><div class="grid grid-3"><div class="card"><div class="card-hd">Peer-Strong Hidden Gems</div><div class="card-sub">Shows that perform better in Bushnell-size venues than nationally.</div><table class="mini-table"><thead><tr><th>Show</th><th class="num">Nat</th><th class="num">Peer</th><th class="num">Gap</th></tr></thead><tbody>${hidden.map(p=>`<tr><td>${p.show.title}</td><td class="num">${pct(p.metrics.cap)}</td><td class="num">${pct(p.metrics.peerCap)}</td><td class="num">+${pct(p.metrics.peerCap-p.metrics.cap)}</td></tr>`).join('')}</tbody></table></div><div class="card"><div class="card-hd">Caution List</div><div class="card-sub">Shows where peer venues trail the full national average.</div><table class="mini-table"><thead><tr><th>Show</th><th class="num">Nat</th><th class="num">Peer</th><th class="num">Gap</th></tr></thead><tbody>${caution.map(p=>`<tr><td>${p.show.title}</td><td class="num">${pct(p.metrics.cap)}</td><td class="num">${pct(p.metrics.peerCap)}</td><td class="num">${pct(p.metrics.peerCap-p.metrics.cap)}</td></tr>`).join('')}</tbody></table></div><div class="card"><div class="card-hd">Subscription Lift</div><div class="card-sub">Shows with the strongest subscription capacity lift.</div><table class="mini-table"><thead><tr><th>Show</th><th class="num">Sub</th><th class="num">Non</th><th class="num">Lift</th></tr></thead><tbody>${subLift.map(p=>`<tr><td>${p.show.title}</td><td class="num">${pct(p.metrics.subCap)}</td><td class="num">${pct(p.metrics.nonSubCap)}</td><td class="num">+${pct(p.metrics.subCap-p.metrics.nonSubCap)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function renderMethodology(){$('tab-methodology').innerHTML=`<div class="section-divider"><h2>Methodology & Definitions</h2><div class="section-divider-line"></div><div class="section-divider-meta">How leadership should read the scoring</div></div><div class="grid grid-2"><div class="method-card"><h3>Fit Score Rubric</h3><p>The Fit Score is a 0–100 directional planning score. It is intentionally conservative: it rewards evidence of demand and peer-market strength, then adjusts for sample depth and subscription signal.</p><div class="formula">Base score: 50<br>+ paid-capacity performance<br>+ gross-potential performance<br>+ Bushnell-size peer performance<br>+ sample-depth adjustment<br>+ subscription lift, when relevant</div><p style="margin-top:10px">Scores should start a conversation, not end one. A lower score may still be the right artistic, mission, or audience-development decision.</p></div><div class="method-card"><h3>Score Bands</h3><p style="font-size:.72rem;color:var(--ink2);margin-bottom:8px">Thresholds are relative to the season median — not fixed percentages. A show above median is a stronger signal given the actual touring market this season.</p><table class="mini-table"><tbody><tr><td><span class="status good">Above Median</span></td><td>Strong evidence of fit for this season's touring market. Review pricing, inventory strategy, and marketing upside.</td></tr><tr><td><span class="status warn">Below Median</span></td><td>Needs review relative to the season slate. May indicate demand risk, pricing sensitivity, or weak peer signal.</td></tr><tr><td><span class="status neutral">NEW</span></td><td>No meaningful historical touring data in this feed. Treat as exploratory upside.</td></tr></tbody></table></div><div class="method-card"><h3>What Are Peers?</h3><p>Peers are classified by type: Size (±10% of Bushnell sellable capacity, 2,450–2,994 seats), Proximity (Northeast/New England markets), Market (comparable nonprofit mid-sized city PACs), and Extended Size (±15% range). A venue may carry multiple classifications.</p><ul><li>Use peer capacity to judge likely room fit.</li><li>Use national capacity to understand overall title demand.</li><li>Use the gap between them to find Hartford-like opportunities and risks.</li></ul></div><div class="method-card"><h3>Confidence Levels</h3><table class="mini-table"><tbody><tr><td><strong>High</strong></td><td>Broad evidence across multiple records and venues.</td></tr><tr><td><strong>Medium</strong></td><td>Useful evidence, but leadership should still apply context.</td></tr><tr><td><strong>Low</strong></td><td>Thin sample; validate with comparable titles or market intelligence.</td></tr><tr><td><strong>Exploratory</strong></td><td>New tour or unmatched title; use comps, pre-sale indicators, and strategic fit.</td></tr></tbody></table></div><div class="method-card full"><h3>Executive Use Guidance</h3><p>This tool is strongest when used as a common language for programming, marketing, and finance. For future seasons, a high score suggests a title has measurable touring support. For previous seasons, the same index should be read retrospectively: a strong result documents what worked, while a low result asks the team what affected demand, pricing, timing, subscription positioning, or mission rationale. The dashboard should not replace leadership judgment; it should make that judgment clearer and better documented.</p></div></div>`;}
function rankItems(items,nameFn,detailFn,valFn){return BTD.components&&BTD.components.rankItems?BTD.components.rankItems(items,nameFn,detailFn,valFn):''}
function destroy(id){if(BTD.charts&&BTD.charts.destroy){BTD.charts.destroy(id);return;} if(CHARTS[id]){CHARTS[id].destroy();delete CHARTS[id];}}
function chartFit(profiles,id){return BTD.charts&&BTD.charts.renderFitChart?BTD.charts.renderFitChart(id,profiles):null}
function chartCap(profiles,id){return BTD.charts&&BTD.charts.renderCapacityComparisonChart?BTD.charts.renderCapacityComparisonChart(id,profiles):null}
function chartPeers(arr){return BTD.charts&&BTD.charts.renderPeerChart?BTD.charts.renderPeerChart('cPeers',arr):null}
function median(arr){return BTD.metrics&&BTD.metrics.median?BTD.metrics.median(arr):65;}
function bushnellRows(show,seasonId){const s=SEASONS.find(x=>x.id===seasonId);if(!s)return[];const key=norm(show.match||show.title);return ALL.filter(d=>d.theatre==='Bushnell'&&norm(d.show).includes(key)&&d.week_of>=s.start&&d.week_of<=s.end);}
function bushnellMetrics(show,seasonId){const rows=bushnellRows(show,seasonId);if(!rows.length)return null;const caps=rows.map(r=>r.cap_paid).filter(x=>x!=null);const grosses=rows.map(r=>r.gross_gross).filter(x=>x!=null);return{cap:caps.length?avg(caps):null,gross:grosses.length?avg(grosses):null,count:rows.length};}
function bushnellBriefCard(profiles,seasonId){const results=profiles.map(p=>{const bm=bushnellMetrics(p.show,seasonId);if(!bm||bm.cap==null)return null;return{title:p.show.title,bCap:bm.cap,nCap:p.metrics.cap,pCap:p.metrics.peerCap};}).filter(Boolean);if(!results.length)return'';const outNat=results.filter(r=>r.nCap!=null&&r.bCap>r.nCap).length;const outPeer=results.filter(r=>r.pCap!=null&&r.bCap>r.pCap).length;const avgB=avg(results.map(r=>r.bCap));const avgN=avg(results.filter(r=>r.nCap!=null).map(r=>r.nCap));const avgP=avg(results.filter(r=>r.pCap!=null).map(r=>r.pCap));const vsN=avgB!=null&&avgN!=null?avgB-avgN:null;const vsP=avgB!=null&&avgP!=null?avgB-avgP:null;return`<div class="card full"><div class="card-hd">Bushnell Results vs Market</div><div class="grid grid-3" style="margin-top:8px"><div class="note"><div class="note-hd">Bushnell Avg Capacity</div><div class="val" style="font-size:1.1rem;font-weight:700">${pct(avgB)}</div><div class="note-body"><span class="status ${vsN==null?'neutral':vsN>=0?'good':'warn'}">${vsN!=null?(vsN>=0?'+':'')+pct(vsN):'—'} vs nation</span> &nbsp; <span class="status ${vsP==null?'neutral':vsP>=0?'good':'warn'}">${vsP!=null?(vsP>=0?'+':'')+pct(vsP):'—'} vs peers</span></div></div><div class="note"><div class="note-hd">Beat National Tour</div><div class="val" style="font-size:1.1rem;font-weight:700">${outNat} <span style="font-size:.7rem;font-weight:400;color:var(--ink2)">of ${results.length} shows</span></div><div class="note-body">shows where Bushnell cap exceeded the national tour avg</div></div><div class="note"><div class="note-hd">Beat Bushnell-Size Peers</div><div class="val" style="font-size:1.1rem;font-weight:700">${outPeer} <span style="font-size:.7rem;font-weight:400;color:var(--ink2)">of ${results.length} shows</span></div><div class="note-body">shows where Bushnell cap exceeded Bushnell-size peer venue avg</div></div></div></div>`;}
function bushnellVsMarketTable(seasonRows,seasonId){const rows=seasonRows.map(p=>({p,bm:bushnellMetrics(p.show,seasonId)}));if(!rows.some(r=>r.bm))return'';return`<div class="card full"><div class="card-hd">Bushnell vs Market</div><div class="card-sub">How the Bushnell engagement compared to the national tour and Bushnell-size peers for each programmed show.</div><table class="mini-table"><thead><tr><th>Show</th><th class="num">Bushnell Cap</th><th class="num">National Avg</th><th class="num">Peer Avg</th><th class="num">vs Nation</th><th class="num">vs Peers</th><th class="num">Bushnell Gross</th></tr></thead><tbody>${rows.map(({p,bm})=>{if(!bm||bm.cap==null)return`<tr><td>${p.show.title}</td><td colspan="6" style="color:var(--ink3);font-size:.62rem">No Bushnell records in feed for this season</td></tr>`;const vsN=p.metrics.cap!=null?bm.cap-p.metrics.cap:null;const vsP=p.metrics.peerCap!=null?bm.cap-p.metrics.peerCap:null;return`<tr><td>${p.show.title}<br><span style="color:var(--ink3);font-size:.58rem">${dateLine(p.show)}</span></td><td class="num"><strong>${pct(bm.cap)}</strong></td><td class="num">${pct(p.metrics.cap)}</td><td class="num">${pct(p.metrics.peerCap)}</td><td class="num"><span class="status ${vsN==null?'neutral':vsN>=0?'good':'warn'}">${vsN!=null?(vsN>=0?'+':'')+pct(vsN):'—'}</span></td><td class="num"><span class="status ${vsP==null?'neutral':vsP>=0?'good':'warn'}">${vsP!=null?(vsP>=0?'+':'')+pct(vsP):'—'}</span></td><td class="num">${fmt$(bm.gross)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function short(s,n){return BTD.page&&BTD.page.short?BTD.page.short(s,n):(s&&s.length>n?s.slice(0,n)+'…':s)}function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
Chart.defaults.font.family = "'Libre Franklin', sans-serif";
Chart.defaults.font.size = 10;
